function catalogMatches(query){const term=query.toLowerCase().trim();const words=term.split(/\s+/).filter(Boolean);return searchCatalog.filter(([name,keywords])=>{const haystack=(name+' '+keywords).toLowerCase();return haystack.includes(term)||words.every(word=>haystack.includes(word))})}
function finds(){const query=searchQuery.trim();const matches=query?catalogMatches(query):searchCatalog.slice(0,6);const cards=(matches.length?matches:[[query||t.search,'',searchHref(query),t.all]]).map(([name,keywords,href,category])=>`<a class="card" href="${href}"><span class="meta">${category}</span><h3>${esc(name)}</h3><p>${query&&matches.length?`${searchLabels[lang]} “${esc(query)}”`:`${t.detailText}`}</p><strong>${cardCtas[lang]}</strong></a>`).join('');return `<main>${intro(t.findTitle,t.findText)}<section class="shell section">${search()}<div class="section-top search-result"><h2>${query?`${searchLabels[lang]} “${esc(query)}”`:t.findTitle}</h2></div><div class="list">${cards}</div></section></main>`}
function searchProduct(q){const term=(q||'').toLowerCase().trim();const exact=directSearchProducts.find(([pattern])=>pattern.test(term));return exact?exact[1]:searchHref(term)}
function articles(){const article=editorial[lang]||editorial.en;return `<main>${intro(t.articleTitle,t.articleText)}<section class="shell section"><article class="article"><span class="meta">${article.meta}</span><h2>${article.title}</h2>${article.sections.map(([h,p])=>`<h3>${h}</h3><p>${p}</p>`).join('')}<a class="btn alt" href="${url('guides')}">${t.guide}</a></article></section></main>`}
function faq(){const questions=faqContent[lang]||faqContent.en;return `<main>${intro(t.faqTitle,t.faqText)}<section class="shell section"><div class="faq">${questions.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section></main>`}
function footer(){return `<footer class="shell footer"><div class="footer-inner"><strong>PikoBuy China</strong><p>${t.footer}<br>${t.disclaimer}</p></div></footer>`}document.documentElement.lang=lang;document.title=(page==='home'?t.hero:document.title);document.getElementById('app').innerHTML=nav()+({home,finds,categories:categoriesPage,details,guides,articles,faq}[page]())+footer();
